/**
 * Where a source's outputs live, and how a generated file names its source.
 *
 * Every path here is relative to the project root and uses `/`, whatever the
 * platform — the same paths end up in git and in the header of each file.
 */
import { posix } from 'node:path';

export interface Outputs {
  /** The Markdown mirror: the source's path with `.md`, under `outDir` if set. */
  readonly markdown: string;
  /** Extracted images: next to the Markdown, named after it. */
  readonly assets: string;
  /** `assets` as written in the Markdown — relative to it and safe inside `(…)`. */
  readonly assetsLink: string;
}

export function outputsFor(source: string, outDir: string | undefined): Outputs {
  const stem = source.replace(/\.docx$/i, '');
  const base = outDir === undefined ? stem : posix.join(outDir, stem);
  return {
    markdown: `${base}.md`,
    assets: `${base}.assets`,
    assetsLink: linkPath(`${posix.basename(base)}.assets`),
  };
}

/** The assets folder that belongs to a generated Markdown file. */
export function assetsOf(markdown: string): string {
  return markdown.replace(/\.md$/, '.assets');
}

/** Percent-encodes only what would end the link or confuse a renderer; keeps Hangul readable. */
function linkPath(path: string): string {
  return path.replace(/[%\s()<>[\]]/g, (c) => `%${c.charCodeAt(0).toString(16).toUpperCase()}`);
}

/**
 * The output format version. It changes whenever the same .docx would convert
 * to different Markdown — a new rule here, or a converter dependency upgrade —
 * and only then: a docx2md release that keeps the output keeps the number, so
 * upgrading the tool does not touch every generated file.
 *
 * Bump it, and record the change in README.md ("출력 형식 버전"), whenever
 * src/convert/format.test.ts fails.
 */
export const FORMAT_VERSION = 1;

const HEADER =
  /^<!-- generated by docx2md \(format (\d+)\) from ("(?:[^"\\]|\\.)*"); edit the \.docx, not this file -->\n/;

/**
 * The first line of every generated file. It is how docx2md recognises its own
 * files — it never overwrites or deletes a Markdown file without it — and
 * which output format wrote them.
 */
export function header(source: string, format = FORMAT_VERSION): string {
  // `>` is escaped so no source name can close the comment early.
  const name = JSON.stringify(source).replace(/>/g, '\\u003e');
  return `<!-- generated by docx2md (format ${format}) from ${name}; edit the .docx, not this file -->\n`;
}

export interface Generated {
  readonly source: string;
  readonly format: number;
}

/** What a generated file's header says, or `undefined` if the file is not generated. */
export function parseHeader(text: string): Generated | undefined {
  const match = HEADER.exec(text);
  if (match?.[1] === undefined || match[2] === undefined) return undefined;
  try {
    const source: unknown = JSON.parse(match[2]);
    return typeof source === 'string' ? { source, format: Number(match[1]) } : undefined;
  } catch {
    return undefined;
  }
}

/** How many leading bytes of a file are enough to read its header. */
export const HEADER_BYTES = 4096;
